Joel 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De quem Joel era filho?","o":["Amoz","Petuel","Beeri","Amitai"],"c":1,"v":1,"e":"O versículo 1 diz que a palavra do Senhor foi dirigida a Joel, filho de Petuel."},
 {"t":"multipla","p":"O que o povo deve fazer com o que aconteceu?","o":["Esquecer e recomeçar","Escrever num livro no templo","Contar aos filhos, de geração em geração","Guardar segredo entre os anciãos"],"c":2,"v":3,"e":"O versículo 3 manda contar aos filhos, e estes aos seus filhos, até a próxima geração."},
 {"t":"multipla","p":"A que são comparados os dentes da nação que veio contra a terra?","o":["Dentes de leão","Dentes de lobo","Dentes de urso","Dentes de serpente"],"c":0,"v":6,"e":"O versículo 6 diz que seus dentes são como os dentes de leão."},
 {"t":"multipla","p":"O que cessou na casa do Senhor?","o":["O cântico dos levitas","O incenso do altar","A leitura da Lei","A oferta de manjares e a libação"],"c":3,"v":9,"e":"O versículo 9 diz que cessou a oferta de manjares e a libação da casa do Senhor."},
 {"t":"multipla","p":"O que o profeta manda santificar?","o":["Um banquete","Um jejum","A colheita","Um altar novo"],"c":1,"v":14,"e":"O versículo 14 diz: santificai um jejum e proclamai um dia sagrado."},
 {"t":"cv","p":"Além da videira e da figueira, também a romeira, a palmeira e a macieira secaram.","c":true,"v":12,"e":"O versículo 12 cita a romeira, a palmeira e a macieira entre as árvores que secaram."},
 {"t":"cv","p":"O capítulo diz que o dia do Senhor ainda está muito distante.","c":false,"v":15,"e":"O versículo 15 diz que o dia do Senhor está próximo."},
 {"t":"cv","p":"Os animais do campo bramam ao Senhor porque os rios de água se secaram.","c":true,"v":20,"e":"O versículo 20 diz que os animais bramam ao Senhor, pois os rios de água se secaram."}
]}

Joel 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Para qual vale o Senhor diz que fará descer todas as nações?","o":["Vale de Josafá","Vale de Sitim","Vale de Hinom","Vale de Acor"],"c":0,"v":2,"e":"No versículo 2, o Senhor diz que congregará todas as nações e as fará descer ao vale de Josafá para entrar em juízo contra elas."},
 {"t":"multipla","p":"Segundo o capítulo, em troca de que venderam uma menina?","o":["Vinho","Prata","Pão","Ouro"],"c":0,"v":3,"e":"O versículo 3 diz que venderam uma menina por vinho, para que se embriagassem."},
 {"t":"multipla","p":"A quem foram vendidos os filhos de Judá e de Jerusalém?","o":["Aos gregos","Aos sabeus","Aos egípcios","Aos edomitas"],"c":0,"v":6,"e":"O versículo 6 diz que os filhos de Judá e de Jerusalém foram vendidos aos filhos dos gregos."},
 {"t":"multipla","p":"O que as nações deviam forjar de suas relhas de arado?","o":["Espadas","Lanças","Escudos","Arcos"],"c":0,"v":10,"e":"O versículo 10 manda forjar espadas das relhas de arado e lanças das podadeiras."},
 {"t":"multipla","p":"Como se chama o vale onde estão as multidões quando o Dia do Senhor se aproxima?","o":["Vale da Decisão","Vale da Bênção","Vale dos Ossos","Vale das Lágrimas"],"c":0,"v":14,"e":"O versículo 14 diz: multidões, multidões no vale da Decisão, porque o Dia do Senhor se aproxima."},
 {"t":"cv","p":"Enquanto os céus e a terra tremem, o Senhor será o refúgio do seu povo.","c":true,"v":16,"e":"O versículo 16 diz que os céus e a terra tremerão, mas o Senhor será o refúgio do seu povo e a fortaleza dos filhos de Israel."},
 {"t":"cv","p":"O capítulo diz que estrangeiros continuarão passando por Jerusalém.","c":false,"v":17,"e":"O versículo 17 diz o contrário: Jerusalém será santa e estrangeiros não passarão mais por ela."},
 {"t":"cv","p":"O Egito e Edom se tornarão desolação por causa da violência que praticaram contra os filhos de Judá.","c":true,"v":19,"e":"O versículo 19 diz que o Egito e Edom ficarão desolados pela violência contra os filhos de Judá, em cuja terra derramaram sangue inocente."}
]}

Joel 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde o capítulo manda tocar a trombeta no início?","o":["Em Sião","Em Betel","Em Samaria","Em Jericó"],"c":0,"v":1,"e":"O versículo 1 abre com a ordem: 'Toca a trombeta em Sião'."},
 {"t":"multipla","p":"Como é a terra diante do povo grande e poderoso?","o":["Como um vale seco","Como o jardim do Éden","Como um mar agitado","Como um campo queimado"],"c":1,"v":3,"e":"O versículo 3 diz que a terra diante dele é como o jardim do Éden, mas atrás dele fica um deserto assolado."},
 {"t":"multipla","p":"O que o Senhor manda rasgar, em vez das vestes?","o":["As tendas","Os véus","O coração","As bandeiras"],"c":2,"v":13,"e":"O versículo 13 diz: 'Rasgai o coração e não as vestes'."},
 {"t":"multipla","p":"Onde os sacerdotes devem chorar e orar?","o":["À porta da cidade","Sobre os muros","No monte das Oliveiras","Entre o pórtico e o altar"],"c":3,"v":17,"e":"O versículo 17 manda os sacerdotes chorarem entre o pórtico e o altar."},
 {"t":"multipla","p":"O que o Senhor diz que vai enviar ao seu povo?","o":["Cereal, vinho e azeite","Ouro, prata e bronze","Ovelhas, bois e cabras","Maná, codornizes e água"],"c":0,"v":19,"e":"No versículo 19 o Senhor diz: 'Eis que vos envio cereal, vinho e azeite'."},
 {"t":"cv","p":"O Senhor promete afastar o exército que vem do sul.","c":false,"v":20,"e":"O versículo 20 fala do exército que vem do norte, não do sul."},
 {"t":"cv","p":"O Senhor promete restituir os anos consumidos pelo gafanhoto, pela locusta, pelo pulgão e pela lagarta.","c":true,"v":25,"e":"O versículo 25 traz essa promessa de restituição."},
 {"t":"cv","p":"Todo aquele que invocar o nome do Senhor será salvo.","c":true,"v":32,"e":"O versículo 32 diz exatamente que todo aquele que invocar o nome do Senhor será salvo."}
]}
